corrected_code:
app.post('/api/payments/default', async (req, res) => {
  const methodId = req.body.method_id;
  await pgClient.query('UPDATE payment_methods SET is_default = false WHERE user_id = $1', [req.user.id]);
  const res = await pgClient.query('UPDATE payment_methods SET is_default = true WHERE id = $1 AND user_id = $2', [methodId, req.user.id]);
  if (res.rowCount === 0) return res.status(403).send();
  res.send('Default updated');
});
